// am — አማርኛ (amárico).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// ---------------------------------------------------------------------------------------------------
// O "VOCÊ" DO AMÁRICO TAMBÉM TEM SEXO — É O MESMO PROBLEMA DO HAUÇÁ, E A MESMA SAÍDA.
//
// Na segunda pessoa do singular, o amárico escolhe entre አንተ (a um homem) e አንቺ (a uma mulher).
// Não é um acento: são duas palavras, e os verbos as acompanham até o fim da frase. O Syden não sabe
// o sexo de quem está lendo, e escolher uma erra com metade das pessoas.
//
// A saída é a forma de cortesia **እርስዎ**, que é NEUTRA e é o que qualquer interface séria em
// amárico usa. Ela puxa a conjugação de plural respeitoso (ይችላሉ, ይምረጡ, ይጻፉ), que é o registro
// natural de um aplicativo falando com quem usa.
//
// É a MESMA decisão do hauçá, por razão idêntica, e vale registrar que já são duas: a pergunta a
// fazer em cada língua nova não é "ela tem tratamento formal?", é **"onde esta língua esconde o
// gênero?"**. No hauçá estava em quem lê; no tailandês, em quem fala; aqui, em quem lê de novo.
//
// Nos BOTÕES e em avisos curtos fica o imperativo simples (ላክ, ሰርዝ, ዝጋ, ቅዳ), que não marca sexo —
// é o mesmo truque que o hauçá usou, e cobre a maior parte da tela de graça.
// ---------------------------------------------------------------------------------------------------
//
// PONTUAÇÃO PRÓPRIA, e ela é da escrita, não enfeite: o ponto final é **።** (U+1362), a vírgula é
// **፣** e os dois-pontos de enumeração são **፦**. Escrever "." e "," num texto em amárico é o
// equivalente a escrever português com ponto chinês. Os três moram no bloco etíope, então o guarda
// de escrita de web/test/traducao.test.ts os aceita sem recorte.
//
// ALGARISMOS, medidos e não supostos: `Intl.NumberFormat('am').format(1234567)` devolve
// `1,234,567` — latinos. O amárico TEM algarismos próprios (፩፪፫…), e eles são o caso em que a
// escrita tradicional perdeu para o uso: hoje aparecem em contexto solene e em datas religiosas, não
// num aplicativo. Os números deste arquivo vão com 0-9. (O Intl também sabe os nomes dos países:
// ET → ኢትዮጵያ, então a grade de países se traduz sozinha.)
//
// FONTE: a escrita etíope não vem na fonte do Syden — entra a Noto Sans Ethiopic, declarada em
// i18n/idiomas.ts. É o caso em que a tela vira quadradinho se a reserva não chegar, e por isso o
// amárico entrou na lista de e2e/configuracoes-traduzidas.mjs.
//
// VOCABULÁRIO, decidido uma vez: comunidade = ማህበረሰብ, canal = ቻናል, sala de voz = የድምፅ ክፍል,
// mensagem = መልእክት, senha = የይለፍ ቃል, lixeira = መጣያ, tópico = ክር (que é literalmente "fio", como
// em português), usuário = ተጠቃሚ, conta = መለያ, administrador = አስተዳዳሪ, dono = ባለቤት,
// cargo = ማዕረግ, convite = ግብዣ, avatar = የመገለጫ ፎቶ, perfil = መገለጫ, transmissão = ስርጭት,
// recado = የድምፅ መልእክት, soundboard = የድምፅ ሰሌዳ, vila = መንደር, loja = ሱቅ.
//
// SELO E INSÍGNIA SEPARADOS, como nas outras línguas: selo = ማህተም (o da comunidade),
// insígnia = ባጅ (a da pessoa). Juntá-los faria a tela dizer que a comunidade ganhou uma medalha.
//
// Palavras que a própria língua já tomou emprestadas ficam como estão (ኢሞጂ, ቪዲዮ, ካሜራ, ማይክሮፎን,
// ሰርቨር, ፋይል, ካራኦኬ, ክሊፕ): traduzi-las por invenção deixaria a tela mais estranha para quem usa,
// não menos.

