  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.': 'ሰው ወደ ማህበረሰቡ ሲገባ የሚያየው የመጀመሪያ ነገር ነው፣ አንድ ጊዜ ብቻ። ይህ ከሌለ፣ በቀጥታ ወደ ቻናሎች ዝርዝር ይገባል።',
