  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'አንድ መልእክት በቂ ⭐ ኮከቦች ሲያገኝ Syden በጎላ መልእክቶች ቻናል ያወጣዋል። የጸሐፊው ኮከብ አይቆጠርም፤ መልእክቱ ሲሰረዝም የጎላው ይሰረዛል።',
