  'O sorteio de {premio} terminou sem participantes.': 'የ{premio} ዕጣ ያለ ተሳታፊ ተጠናቀቀ።',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden ሽልማቱን በቻናሉ ያሳውቃል፤ መሳተፍ የሚፈልግ በ🎉 ምላሽ ይሰጣል። በተወሰነው ሰዓት ምላሽ ከሰጡት መካከል ዕጣ አውጥቶ ውጤቱን ያወጣል።',
