  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'ዛሬ የ{pessoa} የልደት ቀን ነው! 🎉 መልካም ልደት!',
  'Mês': 'ወር',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'ቀኑን ያስገባ ሰው የልደት ቀን ሲደርስ Syden በተመረጠው ቻናል እንኳን ደስ ያለህ ያወጣል። በስሙ ቦታ {pessoa} ይጠቀሙ።',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'ቀኑና ወሩ ብቻ፣ ዓመቱ በጭራሽ። የልደት ቀን የሚያሳውቁ ማኅበረሰቦች በዕለቱ እንኳን ደስ ያለህ ይላሉ። አማራጭ ነው፤ በፈለጉ ጊዜ መሰረዝ ይቻላል።',
