  'O que você fez a respeito?': 'በዚህ ጉዳይ ምን አደረጉ?',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.': 'የመጀመሪያው ምዕራፍ ሲደረስ ማህተሙ እዚህ ይታያል። እስከዚያ ድረስ ተቀምጦ ይቆያል — እና እዚያ መድረስ ራሱ ትርጉሙ ነው።',
  'O selo desta comunidade é': 'የዚህ ማህበረሰብ ማህተም',
  'O som chega quando você abre esta transmissão.': 'ድምፁ የሚመጣው ይህን ስርጭት ሲከፍቱ ነው።',
  'O survival do Léo': 'የLéo survival',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.': 'Syden በእነዚህ ቋንቋዎች ሁሉ መጻፍ ያውቃል — የቀረው የጽሑፎቹ ትርጉም ነው። እስኪደርስ ድረስ ያልተተረጎመው በፖርቱጋልኛ ይታያል፣ የእያንዳንዱ ፊደል ፊደላትም ትክክል ሆነው ይታያሉ፣ ያለ ትናንሽ ሳጥኖች።',
  'O Syden vai ficar fora do ar por uns 10 minutos para uma atualização.': 'Syden ለማሻሻያ ለ10 ደቂቃ ያህል ከአገልግሎት ውጭ ይሆናል።',
  'Observação': 'ማስታወሻ',
  'Oceania': 'ኦሺኒያ',
  'Oceano': 'ውቅያኖስ',
  'Offline': 'ከመስመር ውጭ',
  'Olhe o seu e-mail': 'ኢሜይልዎን ይመልከቱ',
  'Opções': 'አማራጮች',
  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'ከታች ያሉት ምዕራፎች ብቻን ሊደረሱ በማይችሉበት መንገድ ተመርጠዋል — ሁሉም ከአንድ ሰው በላይ፣ በጊዜ ሂደት ይፈልጋሉ።',
  'Os outros idiomas': 'ሌሎቹ ቋንቋዎች',
  'Os outros passam a ouvir o efeito na hora. Você continua sem se escutar.': 'ሌሎች ውጤቱን ወዲያውኑ መስማት ይጀምራሉ። እርስዎ ግን ራስዎን አይሰሙም።',
  'ou': 'ወይም',
