  'Para jogos. Manda uma imagem só, a melhor: sobra máquina para o jogo, e quem assiste recebe o que ela é.': 'ለጨዋታ። አንድ ምስል ብቻ ይልካል፣ ምርጡን፦ ለጨዋታው ማሽን ይተርፋል፣ ተመልካቹም እንዳለ ያገኘዋል።',
  'Parar': 'አቁም',
