  'Procurar GIF': 'GIF ፈልግ',
  'Progresso de {marco}': 'የ{marco} እድገት',
  'Pronto: só este aparelho continua conectado.': 'ተጠናቀቀ፦ ይህ መሣሪያ ብቻ ተገናኝቶ ይቀጥላል።',
  'Pronto. Quem entrar agora vai ver isto.': 'ተጠናቀቀ። አሁን የሚገባ ሰው ይህን ያያል።',
  'Qualidade do compartilhamento de tela': 'የማያ ማጋራት ጥራት',
  'Quatro caracteres, um ícone e uma cor que aparecem ao lado do nome de quem é daqui.': 'አራት ፊደላት፣ አንድ አዶና አንድ ቀለም፣ የዚህ ማህበረሰብ አባል ከሆነ ሰው ስም አጠገብ የሚታዩ።',
  'Que bom te ver de novo.': 'እንደገና በማየቴ ደስ ብሎኛል።',
  'Que legal!': 'በጣም ጥሩ!',
  'Jogando agora': "አሁን እየተጫወቱ ያሉ",
  'Estou aqui': "እዚህ ነኝ",
  'Ao abrir o Syden': "Syden ሲከፈት",
  'No quarto': "በክፍሉ ውስጥ",
  'Onde parei': "ባለፈው ቦታ",
  'Aniversário do Syden': "የSyden ልደት",
  'Hoje é aniversário do Syden!': "ዛሬ የSyden ልደት ነው!",
  'O Syden nasceu em {data}. Valeu por fazer parte desta história.': "Syden የተወለደው {data} ነው። የዚህ ታሪክ አካል ስለሆኑ እናመሰግናለን።",
  'Quem mais cantou': "ብዙ የዘፈነ",
  'Mais cantadas': "በብዛት የተዘፈኑ",
  'Músicas cantadas: {n}': "የተዘፈኑ ዘፈኖች፦ {n}",
  'Ninguém cantou ainda. Conta quando alguém põe uma música com a turma na sala.': "እስካሁን ማንም አልዘፈነም። አንድ ሰው ቡድኑ ክፍሉ ውስጥ እያለ ዘፈን ሲያስጀምር ይቆጠራል።",
  'Idiomas': "ቋንቋዎች",
  'Idiomas falados': "የሚነገሩ ቋንቋዎች",
  'Idiomas em estudo': "በመማር ላይ ያሉ ቋንቋዎች",
  'Aparece no seu cartão de perfil, para quem fala um idioma achar quem o estuda. É opcional.': "በመገለጫ ካርድዎ ላይ ይታያል፤ አንድ ቋንቋ የሚናገር ሰው የሚማረውን እንዲያገኝ። አማራጭ ነው።",
  'Feliz aniversário, {nome}!': 'መልካም ልደት፣ {nome}!',
  'Que este ano venha cheio de boas conversas, boas partidas e boa companhia.': 'ይህ ዓመት በመልካም ውይይቶች፣ በጥሩ ጨዋታዎች እና በመልካም ጓደኝነት የተሞላ ይሁን።',
  'Quem abre o site': 'ጣቢያውን የሚከፍቱ',
  'Quem anda com você': 'ከእርስዎ ጋር የሚሆኑ',
  'Quem canta': 'የሚዘምረው',
  'quem cuida do Syden': 'Syden የሚንከባከቡት',
  'Quem cuida do Syden vai olhar. Obrigado por avisar.': 'Syden የሚንከባከቡት ይመለከቱታል። ስላሳወቁን እናመሰግናለን።',
  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.': 'እዚህ ያለ ሰው መልእክቶችዎን አያይም እርስዎም የእሱን አያዩም፣ ከእርስዎ ጋር የግል ውይይት መክፈት አይችልም እና የጓደኝነት ጥያቄ ሊልክልዎ አይችልም።',
  'Quem estiver na sala será desconectado. Dá para trazer a sala de volta por {dias} dias, em Configurações → Comunidade → Lixeira.': 'በክፍሉ ውስጥ ያለ ሁሉ ይወጣል። ክፍሉን በ{dias} ቀናት ውስጥ መመለስ ይቻላል፣ በቅንብሮች → ማህበረሰብ → መጣያ።',
  'Quem falou': 'የተናገረው',
  'Quem tiver este código entra na comunidade: pela tela de cadastro, se ainda não tem conta, ou pelo botão de entrar, se já usa o Syden.': 'ይህ ኮድ ያለው ሁሉ ወደ ማህበረሰቡ ይገባል፦ መለያ ከሌለው በምዝገባ ገጽ፣ Syden የሚጠቀም ከሆነ በመግቢያ አዝራር።',
  'Quente, mas sem gritar.': 'ሞቅ ያለ፣ ግን የማይጮህ።',
  'Querem falar': 'መናገር ይፈልጋሉ',
  'Rádio de avião': 'የአውሮፕላን ሬዲዮ',
  'Recado': 'የድምፅ መልእክት',
  'Quem dá o recado': 'የድምፅ መልእክቱን የሚያደርሰው ማነው',
  'Recomendado para a maioria. Quem assiste pode baixar a qualidade se precisar.': 'ለአብዛኛው ሰው የሚመከር። ተመልካቹ ካስፈለገው ጥራቱን ዝቅ ማድረግ ይችላል።',
  'Reconectando ao servidor…': 'ከሰርቨሩ ጋር እንደገና በመገናኘት ላይ…',
  'Reduz barulhos de fundo, como teclado, ventilador e trânsito.': 'እንደ ኪቦርድ፣ ማራገቢያና የመንገድ ጫጫታ ያሉ የጀርባ ድምፆችን ይቀንሳል።',
