  'Se existir uma conta com esse endereço, o link para escolher uma senha nova chegou lá. Ele vale por 1 hora.': 'በዚህ አድራሻ መለያ ካለ፣ አዲስ የይለፍ ቃል ለመምረጥ የሚያስችለው አገናኝ ደርሷል። ለ1 ሰዓት ይሰራል።',
