  'Senha definida. Agora dá para entrar com nome e senha também.': 'የይለፍ ቃል ተዘጋጅቷል። አሁን በስምና በይለፍ ቃልም መግባት ይቻላል።',
  'Senha trocada': 'የይለፍ ቃሉ ተቀይሯል',
