  'Seria bom se…': 'ቢሆን ጥሩ ነበር…',
  'Seu microfone está bloqueado: ninguém está te ouvindo.': 'ማይክሮፎንዎ ታግዷል፦ ማንም አይሰማዎትም።',
  'Quem bloqueia é o Windows. Abra Configurações do Windows → Privacidade e segurança → Microfone e ligue o acesso para o navegador.': 'የሚያግደው Windows ነው። የWindows ቅንብሮች → ግላዊነት እና ደህንነት → ማይክሮፎን ይክፈቱና ለአሳሹ ፈቃድ ያብሩ።',
  'Clique no ícone à esquerda do endereço do site, ative o Microfone, e o Syden liga sozinho.': 'ከጣቢያው አድራሻ በስተግራ ያለውን አዶ ጠቅ ያድርጉ፣ ማይክሮፎኑን ያብሩ፣ Syden በራሱ ያስጀምረዋል።',
  'Seu microfone não está mandando som: ninguém está te ouvindo. Clique para escolher outro.': 'ማይክሮፎንዎ ድምፅ እየላከ አይደለም፦ ማንም አይሰማዎትም። ሌላ ለመምረጥ ጠቅ ያድርጉ።',
  'Buscando…': 'በማምጣት ላይ…',
  'Buscar': 'አምጣ',
  'Link do som': 'የድምፅ ሊንክ',
  'ou cole um link (MyInstants, por exemplo)': 'ወይም ሊንክ ይለጥፉ (ለምሳሌ ከMyInstants)',
  'Ouça antes de enviar:': 'ከመላክዎ በፊት ያዳምጡ፦',
  'Não achei o áudio dessa página. No MyInstants, copie o link do botão de baixar e cole aqui.': 'በዚያ ገጽ ላይ ድምፅ አልተገኘም። በMyInstants ላይ የማውረጃ ቁልፉን ሊንክ ቀድተው እዚህ ይለጥፉ።',
  'Esse endereço não é de um arquivo de áudio.': 'ይህ አድራሻ የድምፅ ፋይል አይደለም።',
  'Caixa de ideias (como os outros veem)': 'የሐሳብ ሣጥን (ሌሎች እንደሚያዩት)',
  'É isto que os seus amigos veem aqui embaixo do quarto. O que eles escreverem chega para você como conversa privada, com 💡 na frente — e o Syden já responde agradecendo na hora. Quando a ideia entrar no app, use o joinha na mensagem: do lado deles cai confete e a medalha aparece no perfil.': 'ጓደኞችዎ እዚህ ከክፍሉ በታች የሚያዩት ይህ ነው። የሚጽፉት ከፊቱ 💡 ይዞ እንደ የግል ውይይት ይደርስዎታል — Syden ደግሞ ወዲያውኑ በምስጋና ይመልሳል። ሐሳቡ ወደ መተግበሪያው ሲገባ፣ በመልእክቱ ላይ አውራ ጣት ያድርጉ፦ በእነሱ በኩል ኮንፈቲ ይወርዳል፣ ሜዳሊያውም በመገለጫው ላይ ይታያል።',
  'Entre numa comunidade para ver as salas.': 'ክፍሎቹን ለማየት ማህበረሰብ ይቀላቀሉ።',
  'Escreva um pouco mais sobre a sua ideia.': 'ስለ ሐሳብዎ ትንሽ ተጨማሪ ይጻፉ።',
  'Esta comunidade ainda não tem sala de voz.': 'ይህ ማህበረሰብ እስካሁን የድምፅ ክፍል የለውም።',
  'vazia': 'ባዶ',
  'Serve para recuperar a senha e para avisar você se algo acontecer com o Syden. Sem e-mail, uma senha esquecida não tem volta.': 'የይለፍ ቃል ለማስመለስና በSyden ላይ የሆነ ነገር ቢፈጠር ለማሳወቅ ያገለግላል። ያለ ኢሜይል፣ የተረሳ የይለፍ ቃል አይመለስም።',
