  'Só quem administra pode instalar ou tirar.': 'መጫንም ሆነ ማንሳት የሚችሉት አስተዳዳሪዎች ብቻ ናቸው።',
  'Só quem administra vê este bloco': 'ይህን ክፍል የሚያዩት አስተዳዳሪዎች ብቻ ናቸው',
