  'Sua senha, para confirmar que é você': 'የይለፍ ቃልዎ፣ እርስዎ መሆንዎን ለማረጋገጥ',
  'Sua transmissão está sem som. O navegador só manda o som se você marcar “compartilhar áudio” na janelinha de escolher a tela.': 'ስርጭትዎ ድምፅ የለውም። አሳሹ ድምፁን የሚልከው ማያውን በሚመርጡበት መስኮት ላይ “ድምፅ አጋራ” ሲያመለክቱ ብቻ ነው።',
  'Sua voz': 'ድምፅዎ',
  'Suba músicas que você já tem. Um arquivo': 'ያሉዎትን ዘፈኖች ይጫኑ። የ',
  'Suba só o que é seu ou o que você tem direito de usar. Ter o arquivo não é o mesmo que ter direito de tocar para outras pessoas.': 'የእርስዎ የሆነውን ወይም የመጠቀም መብት ያለዎትን ብቻ ይጫኑ። ፋይሉ መኖሩ ለሌሎች የማሰማት መብት እንዳለዎት አያሳይም።',
  'Sugestões de melhoria': 'የማሻሻያ ሐሳቦች',
  'Supressão de ruído': 'የጫጫታ ማጥፊያ',
  'Também dá para arrastar a borda de cada barra na tela. Dois cliques na borda volta ao padrão.': 'በገጹ ላይ የእያንዳንዱን አሞሌ ጠርዝ መጎተትም ይቻላል። በጠርዙ ላይ ሁለት ጊዜ ጠቅ ማድረግ ወደ ነባሩ ይመልሳል።',
  'Também de graça, e também trocáveis quando quiser. Ficam nas configurações da comunidade, porque valem para a comunidade inteira e não só para você.': 'እነሱም ነፃ ናቸው፣ በፈለጉት ጊዜም ይቀየራሉ። በማህበረሰቡ ቅንብሮች ውስጥ ይገኛሉ፣ ምክንያቱም ለእርስዎ ብቻ ሳይሆን ለመላው ማህበረሰብ ስለሚሰሩ።',
