  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.': 'አንድ ሰው ወደ ክፍልዎ ሲገባ ወይም ሲወጣ፣ አንድ ሰው ማያውን ማጋራት ሲጀምር፣ እና ድምፅዎን ወይም ጆሮዎን ሲያጠፉ ድምፅ ያሰማል።',
  'Tocando…': 'በማጫወት ላይ…',
  'Todas as cores girando devagar. A mais chamativa de todas.': 'ሁሉም ቀለሞች ቀስ ብለው ይሽከረከራሉ። ከሁሉም የሚያስደንቀው።',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.': 'በዚህ ማህበረሰብ ውስጥ ያለ ሁሉ እነዚህን ኢሞጂዎች {exemplo} በመጻፍ ወይም በውይይቱ የኢሞጂ አዝራር መጠቀም ይችላል። ክፍያ የለም፦ ሁሉም ክፍት ነው።',
  'Tom mais alto e mais claro.': 'ከፍ ያለና ጥርት ያለ ቃና።',
  'Tom mais baixo e mais encorpado.': 'ዝቅ ያለና ወፍራም ቃና።',
