  'Tudo aqui é de graça. Escolha o que quiser, troque quando quiser.': 'እዚህ ሁሉም ነገር ነፃ ነው። የፈለጉትን ይምረጡ፣ በፈለጉት ጊዜ ይቀይሩ።',
  'Turma formada': 'ቡድኑ ተሟልቷል',
