  'Últimas quedas': 'የመጨረሻዎቹ መቋረጦች',
  'último dia para trazer de volta': 'ለመመለስ የመጨረሻው ቀን',
  'Um anel claro e discreto.': 'ብሩህና ቀላል ቀለበት።',
  'Um anel quente, cor de cobre velho.': 'ሞቅ ያለ ቀለበት፣ የአሮጌ መዳብ ቀለም።',
  'um canal': 'አንድ ቻናል',
  'Um lugar novo, com canais próprios, e você decide quem entra.': 'አዲስ ቦታ፣ የራሱ ቻናሎች ያሉት፣ እና ማን እንደሚገባ እርስዎ ይወስናሉ።',
  'Um lugar novo, com canais próprios. Você escolhe quem entra pelo código de convite.': 'አዲስ ቦታ፣ የራሱ ቻናሎች ያሉት። ማን እንደሚገባ በግብዣ ኮድ ይመርጣሉ።',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.': 'የተጫነ ጥቅል ለመላው ማህበረሰብ ይሰራል፦ ኢሞጂዎቹ በሁሉም ሰው መልእክቶች ውስጥ መስራት ይጀምራሉ።',
  'Uma imagem larga, de 1200 por 300 ou parecida. GIF animado vale, e anima de verdade. Sem capa, fica a arte que você escolheu nas boas-vindas.': 'ሰፊ ምስል፣ 1200 በ300 ወይም ተመሳሳይ። እንቅስቃሴ ያለው GIF ይሰራል፣ በእውነትም ይንቀሳቀሳል። ሽፋን ከሌለ፣ በእንኳን ደህና መጡ ገጽ የመረጡት ሥዕል ይቀራል።',
  'Usar': 'ተጠቀም',
  'Uso do servidor': 'የሰርቨሩ አጠቃቀም',
  'Vale a partir do próximo compartilhamento.': 'ከሚቀጥለው ማጋራት ጀምሮ ይሰራል።',
  'Vários de uma vez': 'ብዙ በአንድ ጊዜ',
  'Veja se o microfone está captando a sua voz.': 'ማይክሮፎኑ ድምፅዎን እየቀዳ እንደሆነ ይመልከቱ።',
  'Ver mais': 'ተጨማሪ አሳይ',
  'Ver tópico': 'ክሩን ተመልከት',
  'Verde claro.': 'ቀላል አረንጓዴ።',
  'Verde de mato, como a vila.': 'የሳር አረንጓዴ፣ እንደ መንደሩ።',
  'Verde de pedra.': 'የድንጋይ አረንጓዴ።',
  'Verde escuro.': 'ጥቁር አረንጓዴ።',
  'Verde fundo com reflexo.': 'ጥልቅ አረንጓዴ ከነጸብራቅ ጋር።',
  'Verde-água.': 'የውሃ አረንጓዴ።',
