  'Vidro colorido com a luz passando.': 'ብርሃን የሚያልፍበት ባለቀለም መስታወት።',
  'Vila': 'መንደር',
  'Visitas': 'ጉብኝቶች',
  'Vitral': 'ባለቀለም መስታወት ሥዕል',
  'você': 'እርስዎ',
  'Você ainda não está em nenhuma comunidade': 'ገና በማንኛውም ማህበረሰብ ውስጥ አይደሉም',
  'Você ainda não tem amigos no Syden. A aba': 'ገና በSyden ጓደኞች የሉዎትም። ትሩ',
  'Você ainda não tem este item': 'ገና ይህ ዕቃ የለዎትም',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': 'ገና አንድም የለዎትም። እንደ ስጦታ ወይም እንደ ሽልማት ይመጣሉ — ለምሳሌ፣ ሐሳብዎ ወደ Syden ሲገባ።',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': 'በውጭ አገልግሎት ገብተዋል በዚህ መለያ ላይም ገና የይለፍ ቃል የለዎትም። እዚህ አንድ ያዘጋጁ፦ ሁለተኛው የመግቢያ መንገድ ይሆናል፣ ያንን አገልግሎት በኋላ ለማጥፋት የሚያስችለውም ይህ ነው።',
  'Você está silenciado!': 'ድምፅዎ ጠፍቷል!',
  'Você foi convidado. É só escolher um nome, um e-mail e uma senha.': 'ተጋብዘዋል። ስም፣ ኢሜይልና የይለፍ ቃል መምረጥ ብቻ ነው።',
  'Você não bloqueou ninguém.': 'ማንንም አላገዱም።',
  'Você não enviou nenhum pedido.': 'ምንም ጥያቄ አልላኩም።',
  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.': 'የዚህን ማህበረሰብ ቻናሎች ማግኘት ያጣሉ። ለመመለስ አዲስ ግብዣ ያስፈልግዎታል።',
  'Você recebeu um item': 'ዕቃ ደርሶዎታል',
  'Voltar': 'ተመለስ',
  'Voltar ao padrão': 'ወደ ነባሩ ተመለስ',
  'Voltar para a entrada': 'ወደ መግቢያው ተመለስ',
  'Volume': 'የድምፅ መጠን',
  'Volume da transmissão': 'የስርጭቱ ድምፅ መጠን',
  'Volume do soundboard (só para você): {quanto}%': 'የድምፅ ሰሌዳው መጠን (ለእርስዎ ብቻ)፦ {quanto}%',
  'Voz': 'ድምፅ',
  'Voz bem mais grave e pesada.': 'በጣም ጎርናና እና ከባድ ድምፅ።',
  'Voz e vídeo': 'ድምፅና ቪዲዮ',
  'Voz espremida e chiada, como a do piloto no rádio.': 'የተጨመቀና የሚንሾካሾክ ድምፅ፣ እንደ አብራሪው በሬዲዮ።',
  'Voz feminina': 'የሴት ድምፅ',
  'Voz fininha, de desenho animado.': 'ቀጭን ድምፅ፣ እንደ ካርቱን።',
  'Voz masculina': 'የወንድ ድምፅ',
  'Voz metálica de robô de filme antigo.': 'የአሮጌ ፊልም ሮቦት የብረት ድምፅ።',
  'Vozes juntas': 'ድምፆች አብረው',
  'ZECA': 'ZECA',
  'Juntar as vozes da sala': 'የክፍሉን ሰዎች ድምፅም አካትት',
  'Conta excluída': 'የተሰረዘ መለያ',
  'Esta pessoa excluiu a conta. As mensagens daqui não chegam a ninguém.': 'ይህ ሰው መለያውን ሰርዟል። ከዚህ የሚላኩ መልእክቶች ወደ ማንም አይደርሱም።',
  '🤖 Recado automático: sua ideia chegou, obrigado! Vou ler com calma. Se eu tiver dúvida, pergunto por aqui mesmo — e se ela entrar no Syden, você vai saber na hora.': '🤖 ራስ-ሰር መልእክት፦ ሐሳብዎ ደርሷል፣ አመሰግናለሁ! በጥሞና አነበዋለሁ። ጥያቄ ካለኝ እዚሁ እጠይቃለሁ — ወደ Syden ከገባም ወዲያውኑ ያውቃሉ።',
  'A cor do Syden': 'የSyden ቀለም',
  'Vale no app inteiro, só para você.': 'በመተግበሪያው ሁሉ ይሰራል፣ ለእርስዎ ብቻ።',
  'A senha está incorreta.': 'የይለፍ ቃሉ ትክክል አይደለም።',
  'A senha atual está incorreta.': 'አሁን ያለው የይለፍ ቃል ትክክል አይደለም።',
  'A senha precisa ter pelo menos 6 caracteres.': 'የይለፍ ቃሉ ቢያንስ 6 ቁምፊዎች ያስፈልጉታል።',
  'A nova senha precisa ter pelo menos 6 caracteres.': 'አዲሱ የይለፍ ቃል ቢያንስ 6 ቁምፊዎች ያስፈልጉታል።',
  'Esse nome de usuário já está em uso.': 'ያ የተጠቃሚ ስም አስቀድሞ ተይዟል።',
  'Escreva um e-mail válido: é por ele que você confirma a conta.': 'ትክክለኛ ኢሜይል ይጻፉ፦ መለያው የሚረጋገጠው በእሱ ነው።',
  'Falta confirmar o seu e-mail. Abra o link que enviamos para entrar.': 'ኢሜይልዎ ገና አልተረጋገጠም። ለመግባት የላክነውን አገናኝ ይክፈቱ።',
  'Código de convite inválido.': 'የግብዣ ኮዱ ልክ አይደለም።',
  'Pessoa não encontrada.': 'ሰውዬው አልተገኘም።',
  'Canal não encontrado.': 'ቻናሉ አልተገኘም።',
  'Conversa não encontrada.': 'ውይይቱ አልተገኘም።',
  'Comunidade não encontrada.': 'ማህበረሰቡ አልተገኘም።',
  'Mensagem vazia.': 'መልእክቱ ባዶ ነው።',
  'Mensagem longa demais.': 'መልእክቱ በጣም ረጅም ነው።',
  'Sessão inválida. Entre novamente.': 'ክፍለ ጊዜው ልክ አይደለም። እንደገና ይግቡ።',
  'Não foi possível falar com o servidor.': 'ከሰርቨሩ ጋር መገናኘት አልተቻለም።',
