  'O desenho precisa de pelo menos 2 pessoas na sala.': 'ስዕልና ግምት በክፍሉ ውስጥ ቢያንስ 2 ሰዎች ይፈልጋል።',
  'Agora não é hora de escolher.': 'አሁን የመምረጫ ጊዜ አይደለም።',
  'Quem escolhe a palavra é quem vai desenhar.': 'ቃሉን የሚመርጠው የሚስለው ሰው ነው።',
  'Escolha uma das três palavras.': 'ከሦስቱ ቃላት አንዱን ይምረጡ።',
  'Agora não é hora de chutar.': 'አሁን የመገመቻ ጊዜ አይደለም።',
  'Quem desenha não chuta.': 'የሚስለው ሰው አይገምትም።',
  'Só quem desenha mexe no desenho.': 'ስዕሉን መንካት የሚችለው የሚስለው ሰው ብቻ ነው።',
  'Cargos automáticos': 'ራስ-ሰር ሚናዎች',
  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'መጀመሪያ የማህበረሰቡን ሚናዎች በአባላት ውስጥ ይፍጠሩ። ከዚያ በራሳቸው እንዲሰጡ ወደዚህ ይመለሱ።',
  'Cargo de quem entra': 'ለአዲስ ገቢዎች የሚሰጥ ሚና',
  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'ወደ ማህበረሰቡ ለሚገባ እያንዳንዱ አዲስ ሰው እነዚህ ሚናዎች ይሰጣሉ።',
  'Cargos por reação': 'በምላሽ የሚሰጡ ሚናዎች',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden በቻናሉ ላይ ለእያንዳንዱ ሚና አንድ ኢሞጂ ያለው መልዕክት ይለጥፋል። ምላሽ የሰጡ ሚናውን ያገኛሉ፤ ምላሻቸውን ያነሱ ያጡታል።',
  'Apagar o painel': 'ፓነሉን ይሰርዙ',
  'Escolha os seus cargos reagindo aqui embaixo!': 'ከዚህ በታች ምላሽ በመስጠት ሚናዎችዎን ይምረጡ!',
  'Texto do painel': 'የፓነሉ ጽሑፍ',
  'Emoji {n}': 'ኢሞጂ {n}',
  'Cargo {n}': 'ሚና {n}',
  'Mais um emoji': 'ተጨማሪ ኢሞጂ',
  'Publicar o painel': 'ፓነሉን ይለጥፉ',
  'Quais jogos a turma joga, com quantas pessoas e quantas partidas vão até o fim. Só contagem: respostas e desenhos não são guardados. Conta a partir de 12/10/2026.': 'ቡድኑ የትኞቹን ጨዋታዎች እንደሚጫወት፣ በስንት ሰዎች፣ እና ስንት ግጥሚያዎች እስከ መጨረሻ እንደሚዘልቁ። ቆጠራ ብቻ ነው፤ መልሶችና ሥዕሎች አይቀመጡም። ከ12/10/2026 ጀምሮ የተቆጠረ።',
  '{n} dias': '{n} ቀናት',
