  'Até o placar final': 'እስከ መጨረሻው ውጤት',
  'Jogos que ninguém jogou': 'ማንም ያልተጫወታቸው ጨዋታዎች',
  'Até o fim': 'እስከ መጨረሻ',
  'Por partida': 'በአንድ ግጥሚያ',
  'Duração': 'የቆይታ ጊዜ',
  'última em {data}': 'የመጨረሻው {data}',
  'O som': 'ድምፁ',
  'A música': 'ሙዚቃው',
  'O emoji': 'ኢሞጂው',
  'O arquivo': 'ፋይሉ',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) ከSyden ተነስቷል፤ ምክንያቱም {quem} መብቱ የእኛ ነው ብለዋል። ለማተም ፈቃድ ከነበረዎት፣ እዚህ መልሰው ያስረዱ፤ መልስዎ ግምት ውስጥ ይገባል። ይህ እስኪጣራ ድረስ ይዘቱ ተነስቶ ይቆያል። ደንቦቹ ይህ እንዴት እንደሚሠራ በክፍል 4 ያብራራሉ፦ https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}» ተነስቷል።',
  'Saíram junto {n} cópia(s) do mesmo arquivo.': 'አብረው የተነሱ የዚሁ ፋይል ቅጂዎች፦ {n}',
  'Quem subiu recebeu o aviso numa conversa com você.': 'የሰቀሉት ሰው ከእርስዎ ጋር ባለ ውይይት ማሳወቂያው ደርሷቸዋል።',
  'Não havia a quem avisar.': 'የሚያሳውቁት ሰው አልነበረም።',
  'É a retirada número {n} desta pessoa.': 'ይህ ከዚህ ሰው የተነሳው ይዘት ቁጥር {n} ነው።',
  'Direito autoral': 'የቅጂ መብት',
  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'መብቱ ያላቸው ሰዎች ምን እንደሆነና የት እንዳለ በመግለጽ ወደ direitos@syden.chat ይጽፋሉ። በስም ይፈልጉ፣ ያንሱት፣ የሰቀሉት ሰውም ከእርስዎ ጋር ባለ ውይይት ማሳወቂያ ይደርሳቸዋል፤ እዚያም መቃወም ይችላሉ።',
  'Nome do som, da música, do emoji ou do arquivo': 'የድምፁ፣ የሙዚቃው፣ የኢሞጂው ወይም የፋይሉ ስም',
  'Procurar conteúdo': 'ይዘት ይፈልጉ',
  'Procurar': 'ይፈልጉ',
  'Nada com esse nome.': 'በዚህ ስም ምንም የለም።',
  'quem subiu: {nome}': 'የሰቀሉት፦ {nome}',
  '{n} retirada(s) antes': 'ከዚህ በፊት የተነሱ፦ {n}',
  'Quem reclamou (nome e e-mail)': 'ቅሬታ ያቀረቡት (ስምና ኢሜይል)',
  'Quem reclamou': 'ቅሬታ ያቀረቡት',
  'Aviso para quem subiu': 'ለሰቀሉት ሰው የሚላክ ማሳወቂያ',
  'Retirar e avisar': 'ያንሱና ያሳውቁ',
  'Retirar': 'ያንሱ',
  'Retiradas feitas': 'የተነሱ ይዘቶች',
  'Nenhuma retirada até agora.': 'እስካሁን ምንም የተነሳ ይዘት የለም።',
  'Reclamação de {quem}. Quem retirou: {por}.': 'ቅሬታ ያቀረቡት፦ {quem}። ያነሱት፦ {por}።',
  'Tickets': 'ትኬቶች',
  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': 'ከአስተዳደሩ ጋር መነጋገር የሚፈልጉ ሰዎች በማህበረሰቡ መነሻ ገጽ ላይ በርዕስ ትኬት ይከፍታሉ። ትኬቱ በዚያ ሰው እና በአስተዳዳሪዎች መካከል የግል የቡድን ውይይት ይሆናል፤ በውይይቶቻችሁ ዝርዝር ውስጥም ይታያል።',
  'Deixar os membros abrirem tickets': 'አባላት ትኬት እንዲከፍቱ ይፍቀዱ',
  'Abertos': 'ክፍት',
