  'Desligar a conta de {nome}? De 13 a 15 anos, ela fica parada até ser ligada de novo.': 'የ{nome} መለያ ይለያይ? ከ13 እስከ 15 ዓመት፣ እንደገና እስኪገናኝ ድረስ ይቆማል።',
  'Desligar esta conta': 'ይህን መለያ ለይ',
  'Ele entra no Syden com a conta dele (ou cria uma) e abre Configurações → Família.': 'እነሱ በራሳቸው መለያ ወደ Syden ይገባሉ (ወይም አዲስ ይፈጥራሉ) እና ቅንብሮች → ቤተሰብ ይከፍታሉ።',
  'Enviar esta imagem junto (só quem cuida do Syden vê)': 'ይህን ምስል አብሮ ላክ (የSyden ተንከባካቢዎች ብቻ ያዩታል)',
