  'Esta transmissão não está disponível para você.': 'ይህ ስርጭት ለእርስዎ አይገኝም።',
  'Falta ligar a sua conta a um pai, mãe ou responsável. Até lá, as proteções ficam todas ligadas.': 'መለያዎን ከአባት፣ እናት ወይም አሳዳጊ ጋር ማገናኘት ይቀራል። እስከዚያ ድረስ ሁሉም ጥበቃዎች እንደበሩ ይቆያሉ።',
  'Falta ligar a sua conta a um responsável': 'መለያዎን ከአሳዳጊ ጋር ማገናኘት ይቀራል',
  'Família': 'ቤተሰብ',
  'Feito. A pessoa vê o motivo e pode recorrer.': 'ተከናውኗል። ግለሰቡ ምክንያቱን ያያል፣ ይግባኝም ማለት ይችላል።',
  'Gerando…': 'በመፍጠር ላይ…',
  'Gerar o código para o responsável': 'ለአሳዳጊው ኮድ ፍጠር',
  'Grave': 'ከባድ',
  'Idade': 'ዕድሜ',
  'idade não informada': 'ዕድሜ አልተገለጸም',
  'Já ligamos': 'አስቀድመን ተገናኝተናል',
  'Lá, digita o código. O código vale 7 dias.': 'እዚያ ኮዱን ያስገባሉ። ኮዱ ለ7 ቀናት ያገለግላል።',
