  'Levar seus dados': 'ውሂብዎን ይውሰዱ',
  'Ligar a conta de um filho': 'የልጅ መለያ አገናኝ',
  'Ligar as contas': 'መለያዎቹን አገናኝ',
  'Ligue a sua conta a um responsável até {data}, em Configurações → Família.': 'እስከ {data} ድረስ መለያዎን ከአሳዳጊ ጋር በቅንብሮች → ቤተሰብ ያገናኙ።',
  'Limite de uso por dia (minutos; vazio é sem limite)': 'የቀን አጠቃቀም ገደብ (ደቂቃዎች፤ ባዶ ማለት ገደብ የለም)',
  'Limite inválido: de 15 minutos a 24 horas.': 'ልክ ያልሆነ ገደብ፦ ከ15 ደቂቃ እስከ 24 ሰዓት።',
  'Mande este código para o seu pai, mãe ou responsável.': 'ይህን ኮድ ለአባትዎ፣ ለእናትዎ ወይም ለአሳዳጊዎ ይላኩ።',
  'Marcar como grave': 'እንደ ከባድ ምልክት አድርግ',
  'Marcar como resolvida': 'እንደተፈታ ምልክት አድርግ',
  'Mensagem': 'መልእክት',
  'Motivo:': 'ምክንያት፦',
  'Na conta dele, em Configurações → Família, aparece um código. Digite aqui.': 'በእነሱ መለያ፣ በቅንብሮች → ቤተሰብ ውስጥ፣ ኮድ ይታያል። እዚህ ያስገቡት።',
  'Não deu para gerar o arquivo agora. Tente de novo.': 'ፋይሉን አሁን መፍጠር አልተቻለም። እንደገና ይሞክሩ።',
  'Não é grave': 'ከባድ አይደለም',
  'Nenhum.': 'ምንም።',
  'nos últimos 7 dias: {tempo}': 'ባለፉት 7 ቀናት፦ {tempo}',
  'O limite combinado com o seu responsável é de {n} minutos por dia. Amanhã, o Syden abre de novo.': 'ከአሳዳጊዎ ጋር የተስማሙበት ገደብ በቀን {n} ደቂቃ ነው። ነገ Syden እንደገና ይከፈታል።',
  'O motivo (a pessoa vai ler)': 'ምክንያቱ (ግለሰቡ ያነበዋል)',
  'O seu recurso foi recebido em {quando}. Quem cuida do Syden vai ler e responder.': 'ይግባኝዎ በ{quando} ደርሷል። የSyden ተንከባካቢዎች አንብበው ይመልሳሉ።',
  'O seu responsável': 'አሳዳጊዎ',
  'O seu tempo de hoje acabou': 'የዛሬው ጊዜዎ አልቋል',
  'O Syden é para quem tem 13 anos ou mais.': 'Syden ዕድሜያቸው 13 እና ከዚያ በላይ ለሆኑ ነው።',
  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'Syden ዕድሜያቸው 13 እና ከዚያ በላይ ለሆኑ ነው። ቀንዎን ማንም አያየውም።',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'Syden ከ18 ዓመት በታች ያሉትን ለመጠበቅ (የECA Digital ሕግ) የሁሉንም ሰው ዕድሜ መጠየቅ ጀምሯል። ቀንዎን ማንም አያየውም፤ የሚጠቀመው የዕድሜ ክልሉ ብቻ ነው።',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'ለማን እንደተነገረና የጉዳዩ ቁጥር (ለምሳሌ፦ SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'ለደህንነት ሲባል፣ የስርጭቶች ቅድመ-እይታ ከ18 ዓመት በታች ላሉ ተዘግቷል።',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'ለደህንነት ሲባል፣ ከ18 ዓመት በታች ያሉ የግል ውይይት የሚያደርጉት ከጓደኞች ጋር ብቻ ነው።',
  'Qual é a sua data de nascimento?': 'የትውልድ ቀንዎ መቼ ነው?',
  'Quem muda estas regras é o seu responsável.': 'እነዚህን ደንቦች የሚቀይረው አሳዳጊዎ ነው።',
  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': 'ዕድሜያቸው ከ13 እስከ 15 የሆኑ Sydenን የሚጠቀሙት ከአባት፣ እናት ወይም አሳዳጊ መለያ ጋር በተገናኘ መለያ ነው። ሕጉ ነው (ECA Digital)፣ ለእርስዎም ደህንነት ነው።',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': 'ከ18 ዓመት በታች ያሉ Sydenን በተጨማሪ ጥበቃዎች ይጠቀማሉ፣ ከ13 እስከ 15 ያሉ ደግሞ ከአሳዳጊ መለያ ጋር በተገናኘ መለያ (የECA Digital ሕግ)።',
  'Recorrer da decisão': 'ይግባኝ ጠይቅ',
  'Recurso em {quando}:': 'ይግባኝ በ{quando}፦',
  'Registrar a comunicação': 'ሪፖርቱን መዝግብ',
  'Só contas de menores de idade se ligam a um responsável.': 'ከአሳዳጊ ጋር የሚገናኙት ከ18 ዓመት በታች ያሉ መለያዎች ብቻ ናቸው።',
  'Só um adulto pode ser o responsável por outra conta.': 'የሌላ መለያ አሳዳጊ መሆን የሚችለው አዋቂ ብቻ ነው።',
  'Sua conta tem uma pendência. Abra o Syden de novo para ver o que fazer.': 'መለያዎ ያልተጠናቀቀ ጉዳይ አለው። ምን ማድረግ እንዳለብዎ ለማየት Sydenን እንደገና ይክፈቱ።',
  'Suspender por idade': 'በዕድሜ ምክንያት አቋርጥ',
  'suspensa por idade': 'በዕድሜ ምክንያት ተቋርጧል',
  'Também dá para escrever para contato@syden.chat.': 'ወደ contato@syden.chat መጻፍም ይችላሉ።',
