  // O cartão das peças do quarto e do salão (17/10/2026)
  'Macio e baixinho, fácil de puxar para perto da conversa.': 'ለስላሳና ዝቅ ያለ፣ ወደ ውይይቱ በቀላሉ የሚጠጋ።',
  'Funda e confortável, boa para ler ou ver alguém jogar.': 'ጥልቅና ምቹ፣ ለማንበብ ወይም ሌላ ሰው ሲጫወት ለማየት ጥሩ።',
