  'São seis cores: escolha a dele no Editar.': 'ስድስት ቀለሞች አሉ፦ የእሱን በአርትዕ ውስጥ ይምረጡ።',
  'O coelho senta aqui quando você entra numa call.': 'እርስዎ ጥሪ ሲገቡ ጥንቸሉ እዚህ ይቀመጣል።',
  'Folhas grandes para encher um canto de verde.': 'አንድን ጥግ በአረንጓዴ የሚሞሉ ትላልቅ ቅጠሎች።',
  'Pequena e cheia, num cesto de palha.': 'ትንሽና ጥቅጥቅ ያለ፣ በገለባ ቅርጫት ውስጥ።',
  'Mostra quem está transmitindo agora.': 'አሁን የሚያሰራጨውን ያሳያል።',
  'Cabe a turma inteira na frente da TV.': 'ቡድኑ በሙሉ በቲቪው ፊት ይበቃል።',
  'Baixinha, perto do sofá, para a pipoca e o refrigerante.': 'ዝቅ ያለ፣ ከሶፋው አጠገብ፣ ለፋንዲሻና ለለስላሳ መጠጥ።',
  'Abre os mini-games para jogar com a turma.': 'ከቡድኑ ጋር ለመጫወት ሚኒ-ጨዋታዎችን ይከፍታል።',
  'Cada prateleira guarda os canais da comunidade.': 'እያንዳንዱ መደርደሪያ የማህበረሰቡን ቻናሎች ይይዛል።',
  'Onde o coelho do recado espera quem chega.': 'የመልእክቱ ጥንቸል የሚመጡትን የሚጠብቅበት።',
