  'Redonda, para cartas, tabuleiro e conversa.': 'ክብ፣ ለካርታ፣ ለሰሌዳ ጨዋታና ለውይይት።',
  'De madeira, com o assento estofado.': 'ከእንጨት የተሠራ፣ ለስላሳ መቀመጫ ያለው።',
