  'Recados e ideias presos com alfinete.': 'በፒን የተሰኩ መልእክቶችና ሀሳቦች።',
  'Livros, uma plantinha e um vaso.': 'መጻሕፍት፣ ትንሽ ተክልና የአበባ ማስቀመጫ።',
  'Um pôr do sol sobre os campos.': 'በሜዳዎች ላይ የፀሐይ መጥለቅ።',
  'Xícaras, potes e garrafas de suco.': 'ኩባያዎች፣ ማሰሮዎችና የጭማቂ ጠርሙሶች።',
  'Potes de biscoito e pipoca para dividir.': 'ለመካፈል የብስኩትና የፋንዲሻ ማሰሮዎች።',
