  'O cartaz do karaokê, em três versões: palco, neon e fogo.': 'የካራኦኬ ፖስተር፣ በሦስት ዓይነት፦ መድረክ፣ ኒዮንና እሳት።',
  'Dois coelhos, um café e a fofoca do dia.': 'ሁለት ጥንቸሎች፣ አንድ ቡናና የዕለቱ ወሬ።',
  'Café quentinho, ainda soltando fumaça.': 'ገና የሚጨስ ትኩስ ቡና።',
  'Suco de laranja com canudinho.': 'ከመምጠጫ ጋር የብርቱካን ጭማቂ።',
