  'Uma pilha de livros para ler depois.': 'በኋላ የሚነበቡ የመጻሕፍት ክምር።',
  'O console da turma, com o controle ao lado.': 'የቡድኑ ኮንሶል፣ መቆጣጠሪያው አጠገቡ።',
  'Um balde de pipoca para ver a transmissão.': 'ስርጭቱን ለማየት አንድ ባልዲ ፋንዲሻ።',
  'Uma lembrança num porta-retrato.': 'በፎቶ ፍሬም ውስጥ ያለ ትዝታ።',
  'Uma pizza inteira para dividir.': 'ለመካፈል ሙሉ ፒዛ።',
