  'Sal e areia': 'ጨውና አሸዋ',
  'Leite e mel': 'ወተትና ማር',
  'De que cor é a folha da cenoura?': 'የካሮት ቅጠል ቀለሙ ምንድን ነው?',
  'Preta': 'ጥቁር',
  'Verde': 'አረንጓዴ',
  'No quarto, onde o coelho dorme quando a pessoa está ausente?': 'በክፍሉ ውስጥ ሰውየው በሌለበት ጊዜ ጥንቸሉ የት ይተኛል?',
  'Na banheira': 'በገንዳው ውስጥ',
  'Na cama': 'በአልጋው ላይ',
  'No telhado': 'በጣሪያው ላይ',
  'No quarto, o que leva às salas de voz?': 'በክፍሉ ውስጥ ወደ የድምፅ ክፍሎች የሚወስደው ምንድን ነው?',
  'O fone': 'የጆሮ ማዳመጫው',
  'O abajur': 'የጠረጴዛ መብራቱ',
  'O vaso': 'የአበባ ማስቀመጫው',
  'No quarto, o que abre os Mini-games?': 'በክፍሉ ውስጥ ሚኒ ጨዋታዎችን የሚከፍተው ምንድን ነው?',
  'A cama': 'አልጋው',
