  'A mesa': 'ጠረጴዛው',
  'No salão da comunidade, o que abre os Mini-games?': 'በማኅበረሰቡ አዳራሽ ውስጥ ሚኒ ጨዋታዎችን የሚከፍተው ምንድን ነው?',
  'O fliperama': 'የመጫወቻ ማሽኑ',
  'A estante': 'መደርደሪያው',
