  'No salão, a TV leva aonde?': 'በአዳራሹ ውስጥ ቴሌቪዥኑ ወዴት ይወስዳል?',
  'Ao guarda-roupa': 'ወደ ልብስ ቁም ሣጥኑ',
  'À sala de voz': 'ወደ የድምፅ ክፍሉ',
  'Ao calendário': 'ወደ የቀን መቁጠሪያው',
  'Qual destes bichos é uma praga da horta?': 'ከእነዚህ እንስሳት ውስጥ የአትክልት ተባይ የትኛው ነው?',
  'Lagarta': 'አባ ጨጓሬ',
  'Quem ajuda as flores a virar frutos?': 'አበባዎች ፍሬ እንዲሆኑ የሚረዳው ማን ነው?',
  'Lesma': 'ቀንድ አውጣ',
  'Quantas patas tem um coelho?': 'ጥንቸል ስንት እግር አለው?',
  'Seis': 'ስድስት',
  'O que nasce de uma semente?': 'ከዘር ምን ይበቅላል?',
  'Uma pedra': 'ድንጋይ',
  'Uma nuvem': 'ደመና',
  'Uma planta': 'ተክል',
  'Quantas rodadas tem uma partida da Festa dos coelhos?': 'የጥንቸሎች ድግስ ጨዋታ ስንት ዙር አለው?',
  'Cinco': 'አምስት',
  'Dez': 'አሥር',
  'Em que dia é o aniversário do Syden?': 'የSyden ልደት በየትኛው ቀን ነው?',
  '1º de janeiro': 'ጃንዋሪ 1',
  '19 de setembro': 'ሴፕቴምበር 19',
  '25 de dezembro': 'ዲሴምበር 25',
  'Na Corrida dos coelhos, o kart do mascote parece o quê?': 'በጥንቸሎች ውድድር ውስጥ የማስኮቱ ካርት ምን ይመስላል?',
  'Um sapato': 'ጫማ',
  'Uma banana': 'ሙዝ',
  'Uma cenoura': 'ካሮት',
  'Qual destes é uma fruta vermelha?': 'ከእነዚህ ውስጥ ቀይ ፍራፍሬ የትኛው ነው?',
  'Batata': 'ድንች',
  'Que bicho é o mascote do Syden?': 'የSyden ማስኮት ምን እንስሳ ነው?',
  'O que a minhoca faz pela horta?': 'የምድር ትል ለአትክልት ቦታው ምን ያደርጋል?',
  'Come as folhas': 'ቅጠሎቹን ይበላል',
  'Espanta a chuva': 'ዝናቡን ያባርራል',
  'Afofa a terra': 'አፈሩን ያለሰልሳል',
  'Qual destes é o mais pesado?': 'ከእነዚህ ውስጥ በጣም ከባዱ የትኛው ነው?',
  'Uma abóbora': 'ዱባ',
  'Uma ervilha': 'አተር',
  'Um morango': 'እንጆሪ',
  'Quem fica atrás do balcão do salão?': 'ከአዳራሹ ባንኮኒ ጀርባ ማን ይቆማል?',
  'Um gato': 'ድመት',
  'O coelho do recado': 'የመልእክቱ ጥንቸል',
  'Ninguém': 'ማንም',
  'O que a estante de troféus do quarto mostra?': 'በክፍሉ ውስጥ ያለው የዋንጫ መደርደሪያ ምን ያሳያል?',
  'Os livros': 'መጻሕፍቱን',
  'As fotos': 'ፎቶዎቹን',
  'Os pódios dos jogos': 'የጨዋታዎቹን መድረኮች',
  'O que um espantalho espanta?': 'የወፍ ማስፈራሪያው ምንን ያባርራል?',
  'Os pássaros': 'ወፎቹን',
  'A chuva': 'ዝናቡን',
  'As minhocas': 'የምድር ትሎቹን',
  'Quantas patas tem uma aranha?': 'ሸረሪት ስንት እግር አላት?',
  'Oito': 'ስምንት',
  'Quantas patas tem um inseto?': 'ነፍሳት ስንት እግር አላቸው?',
  'Na Caça às pragas, o que serve de munição?': 'በጓሮ ተባይ አደን ውስጥ እንደ ጥይት የሚያገለግለው ምንድን ነው?',
  'Cenouras': 'ካሮቶች',
  'Pedras': 'ድንጋዮች',
  'Bolinhas': 'ትናንሽ ኳሶች',
  'No quarto, o que troca o dia pela noite?': 'በክፍሉ ውስጥ ቀንን በሌሊት የሚቀይረው ምንድን ነው?',
  'O tapete': 'ምንጣፉ',
  'A planta': 'ተክሉ',
  'O que dá para fazer com os móveis do seu quarto?': 'በክፍልዎ ዕቃዎች ምን ማድረግ ይቻላል?',
