  'Quiz relâmpago': 'ፈጣን ጥያቄ',
  'Escolha a resposta certa antes que o tempo acabe.': 'ጊዜው ከማለቁ በፊት ትክክለኛውን መልስ ይምረጡ።',
  'Balsa a dois': 'የሁለት ሰው ጀልባ',
