  'Estratégia em tempo real contra o computador: colete comida, madeira e ouro, construa a vila, avance de era e treine o exército. Ganha quem derrubar o centro da vila do outro, ou construir a Maravilha e mantê-la de pé por 2 minutos.': 'ከኮምፒውተር ጋር የሚደረግ የእውነተኛ ጊዜ ስትራቴጂ፦ ምግብ፣ እንጨትና ወርቅ ይሰብስቡ፣ መንደሩን ይገንቡ፣ ወደ ቀጣዩ ዘመን ይሻገሩ፣ ሠራዊቱንም ያሰልጥኑ። የሌላውን የመንደር ማዕከል ያፈረሰ፣ ወይም ድንቁን ገንብቶ ለ2 ደቂቃ ያቆመ ያሸንፋል።',
