  'O computador terminou uma Maravilha: derrube-a em 2 minutos!': 'ኮምፒውተሩ ድንቅ ጨረሰ፦ በ2 ደቂቃ ውስጥ ያፍርሱት!',
  'A sua vila está sob ataque!': 'መንደርዎ ጥቃት ላይ ነው!',
