  'Este jogo não se joga na sala.': 'ይህ ጨዋታ በክፍሉ ውስጥ አይጫወትም።',
  'Ponha os seus navios no mar.': 'መርከቦችዎን ባሕሩ ላይ ያስቀምጡ።',
  'Esperando {nome} pôr os navios…': '{nome} መርከቦችን እስኪያስቀምጡ በመጠበቅ ላይ…',
  'Os dois estão pondo os navios…': 'ሁለቱም መርከቦቻቸውን እያስቀመጡ ነው…',
  'Navio de {n} casas': 'የ{n} ሳጥን መርከብ',
  'Seus navios': 'መርከቦችዎ',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'መርከብ ይምረጡና ባሕሩን ይንኩ። ቦታ ለመቀየር ይጎትቱ።',
  'Sortear a frota': 'የዘፈቀደ መርከቦች',
  'Sua frota já está pronta.': 'መርከቦችዎ አስቀድመው ዝግጁ ናቸው።',
  'Ponha todos os navios antes.': 'መጀመሪያ ሁሉንም መርከቦች ያስቀምጡ።',
  'Escolha um navio.': 'መርከብ ይምረጡ።',
  'O navio não cabe aí.': 'መርከቡ እዚያ አይገባም።',
  'Os navios não podem encostar um no outro.': 'መርከቦቹ እርስ በርስ መነካካት አይችሉም።',
  'Minigolfe 3D': '3D ሚኒ ጎልፍ',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'ስምንት የ3D ጉድጓዶች፣ ከመወጣጫዎች፣ ከቤተ መንግሥትና ከነፋስ ወፍጮ ጋር፤ ሁሉም በአንድ ጊዜ ተመሳሳዩን ይጫወታሉ። ለማነጣጠርና ኃይል ለመስጠት ይጎትቱ፣ ከዚያ ይልቀቁ። አሸናፊነቱ የጥቂት ምቶች ባለቤት ነው።',
  'Ver o buraco de cima': 'ጉድጓዱን ከላይ ይመልከቱ',
  'Fora da pista! Mais uma tacada.': 'ከመንገዱ ወጣ! አንድ ተጨማሪ ምት።',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'ለማነጣጠር ወደ ጎን፣ ለኃይል ወደ ታች ይጎትቱ፣ ከዚያ ይልቀቁ። በቁልፍ ሰሌዳ፦ ቀስቶቹ ያነጣጥራሉ፣ ተጭኖ የተያዘው ስፔስ ደግሞ ኃይል ይሰጣል።',
  'Futebol dos coelhos': 'የጥንቸሎቹ እግር ኳስ',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'በትንሽ ሜዳ የሚደረግ እግር ኳስ፣ ከላይ የሚታይ። ኳሱን ለመንዳት ይንኩት፣ በኃይል ለመምታት ስፔስን ተጭነው ይያዙ፣ በX ያቀብሉ። በክፍሉ ውስጥ ቡድኖቹ በሮቦቶች ይሟላሉ።',
  'Quantos por time?': 'በቡድን ስንት?',
  'Seu time venceu!': 'ቡድንዎ አሸነፈ!',
  'Seu time perdeu.': 'ቡድንዎ ተሸነፈ።',
