  'Ninguém para jogar.': 'የሚጫወት ሰው የለም።',
  'Caça às pragas da horta': 'የጓሮ ተባይ አደን',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'ቁራዎችና አንበጣዎች ጓሮውን እያጠቁ ነው። ከማምለጣቸው በፊት ለመምታት ያነጣጥሩና ይጫኑ፦ ጥይቱ የተወሰነ ነው፣ እያንዳንዱ ማዕበልም ይበልጥ ፈጥኖ ይመጣል። ብዙ ነጥብ ያገኘ ያሸንፋል።',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'ተባዮቹ ከማምለጣቸው በፊት ያነጣጥሩና ይጫኑ። እያንዳንዱ ተኩስ አንድ ካሮት ይጨርሳል።',
