  'Setas para andar, X para bater (três seguidas é o combo), Z para pular, C para o especial, que gasta um pouco de vida.': 'ለመራመድ ቀስቶች፣ ለመምታት X (በተከታታይ ሶስት ጊዜ ኮምቦ ነው)፣ ለመዝለል Z፣ ትንሽ ሕይወት ለሚያስከፍለው ልዩ እንቅስቃሴ C።',
  'Andar': 'መራመድ',
