  'Total': 'ድምር',
  'Tacadas: {n}': 'ምቶች፦ {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'ኳሱን ወደ ኋላ ይጎትቱና ይልቀቁ። በቁልፍ ሰሌዳ፦ ቀስቶቹ ያነጣጥራሉ፣ ተጭኖ የተያዘው ስፔስ ደግሞ ኃይል ይሰጣል።',
  'Na água! Mais uma tacada.': 'ውሃ ውስጥ! አንድ ተጨማሪ ምት።',
  'No buraco!': 'ጉድጓድ ውስጥ!',
