  '{nome} vendeu prédios e hipotecou cidades para pagar ({valor}).': '{nome} ለመክፈል ({valor}) ሕንፃዎችን ሸጠው ከተሞችን በመያዣ ሰጥተዋል።',
  '{nome} faliu e as cidades voltaram ao banco.': '{nome} ከስረዋል፤ ከተሞቹም ወደ ባንኩ ተመልሰዋል።',
