  'Até sobrar um': 'አንድ ሰው እስኪቀር',
  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'በብራዚል ዋና ከተሞች ይዘዋወሩ፣ ከተሞችን ይግዙ፣ በእነሱ ላይ ከሚቆሙትም ኪራይ ይሰብስቡ። ሙሉ ክልል ሲኖርዎት ሕንፃዎችን መገንባት ይችላሉ። ይለዋወጡ፣ በጨረታዎች ይወዳደሩ፣ ገንዘብም እንዳያልቅብዎ ይጠንቀቁ።',
