  'Figurinhas': 'ስቲከሮች',
  'Figurinha não encontrada.': 'ስቲከሩ አልተገኘም።',
  'A sua coleção de figurinhas está cheia. Tire alguma para pôr outra.': 'የስቲከር ስብስብዎ ሞልቷል። ሌላ ለማስገባት አንዱን ያንሱ።',
  'Figurinha': 'ስቲከር',
