  'Salvar figurinha': 'ስቲከሩን ማስቀመጥ',
  'Essa imagem é grande demais para virar figurinha (até 1 MB).': 'ይህ ምስል ስቲከር ለመሆን በጣም ትልቅ ነው (እስከ 1 MB)።',
  'Use uma imagem PNG, JPG, GIF ou WEBP.': 'PNG፣ JPG፣ GIF ወይም WEBP ምስል ይጠቀሙ።',
