  'Criar figurinha': 'ስቲከር መፍጠር',
  'Tirar o fundo': 'ጀርባውን ማስወገድ',
  'Contorno': 'ዙሪያ መስመር',
  'O fundo não é de uma cor só, e ficou como veio.': 'ጀርባው አንድ ቀለም ስላልሆነ እንዳለ ቀርቷል።',
  'No app do Syden, o recorte funciona com qualquer fundo.': 'በSyden መተግበሪያ ውስጥ ማንኛውም ጀርባ ይወገዳል።',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'በሞዴሉ ማስወገድ አልተሳካም፣ ስለዚህ ቀላሉ ማስወገጃ ጥቅም ላይ ዋለ።',
  'Mandar figurinha': 'ስቲከር መላክ',
  'Tirar figurinha': 'ስቲከሩን ማንሳት',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'በምስሎችዎ ስቲከሮችን ይፍጠሩ፣ ወይም በውይይት የሚቀበሏቸውን ያስቀምጡ።',
  'Dominó': 'ዶሚኖ',
  'Truco': 'ትሩኮ',
  'Damas': 'ዳማ',
  'Batalha naval': 'የባሕር ውጊያ',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'የተለመደው ዶሚኖ፣ ከ2 እስከ 4 ሰዎች (4 ሲሆኑ በጥንድ)። ድንጋዮቹን በጫፎቹ ያገናኙ፤ መጀመሪያ የጨረሰ የሌሎችን የእጅ ነጥቦች ይወስዳል።',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'የብራዚል ትሩኮ፣ ከተገለበጠ ካርድ እና ከማኒላ ጋር፣ በ2 ወይም በ4 በጥንድ። ትሩኮ ይጠይቁ፣ ወደ ስድስት፣ ዘጠኝ እና አሥራ ሁለት ያሳድጉ፣ ወይም ይሽሹ። 12 ነጥብ ያደረሰ ያሸንፋል።',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'የብራዚል ዳማ፦ መብላት ግዴታ ነው፣ ወደ ፊትም ወደ ኋላም፤ ንጉሡም ሙሉውን ሰያፍ ይሄዳል። ክፍሉ ይመለከታል።',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'እያንዳንዱ ሰው መርከቦቹን ይደብቃል፣ በሌላው ባሕር ላይም ይተኩሳል። ከመቱ እንደገና ይተኩሳሉ። መጀመሪያ ሁሉንም መርከቦች ያሰመጠ ያሸንፋል። ክፍሉ ይመለከታል።',
